    # Authenticate by id or key_prefix
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and (r.get("id") == api_key_s or r.get("key_prefix") == api_key_s):
            key_row = r
            break
    if not key_row:
        _log_call("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key")

    key_id = key_row.get("id")
    if key_row.get("status") != "active":
        _log_call("error", key_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active (business rule: suspended/revoked keys are rejected)")

    # Quota enforcement: cancellation is still a request.
    limit = key_row.get("daily_request_limit")
    if not isinstance(limit, int) or limit < 0:
        _log_call("error", key_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "API key has invalid daily_request_limit configuration")

    usage_row = None
    for u in usage_daily:
        if isinstance(u, dict) and u.get("api_key_id") == key_id and u.get("usage_date") == day_iso:
            usage_row = u
            break
    if usage_row is None:
        usage_row = {
            "id": _new_id("serp_usg"),
            "api_key_id": key_id,
            "usage_date": day_iso,
            "requests_total": 0,
            "serp_fetches_total": 0,
            "jobs_started_total": 0,
            "jobs_succeeded_total": 0,
            "jobs_failed_total": 0,
            "status": "open",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_daily.append(usage_row)

    if usage_row.get("status") == "sealed":
        _log_call("error", key_id, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily usage is sealed for this API key/date")

    cur_req = usage_row.get("requests_total")
    if not isinstance(cur_req, int) or cur_req < 0:
        cur_req = 0
    if cur_req + 1 > limit:
        _log_call("error", key_id, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", limit=limit)

    usage_row["requests_total"] = cur_req + 1
    usage_row["updated_at"] = now_iso
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("usage_daily.json", usage_daily)
    _save("api_keys.json", api_keys)

    # Find job: strict by id if a real job id; else allow lenient "job_id" pointing to key => cancel most recent in-flight job.
    job = None
    if job_id_s.startswith("serp_job_"):
        for j in analysis_jobs:
            if isinstance(j, dict) and j.get("id") == job_id_s and j.get("api_key_id") == key_id:
                job = j
                break
        if not job:
            _log_call("error", key_id, "NOT_FOUND", meta={"job_id": job_id_s})
            return _err("NOT_FOUND", "Job not found (business rule: job must exist and belong to the authenticated key)")
    else:
        # Lenient fallback used by audit: cancel the most recent queued/running job for this key.
        inflight = []
        for j in analysis_jobs:
            if isinstance(j, dict) and j.get("api_key_id") == key_id and j.get("status") in ("queued", "running"):
                inflight.append(j)
        def _parse_dt(s):
            if not isinstance(s, str) or not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        inflight.sort(key=lambda r: (_parse_dt(r.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
        if inflight:
            job = inflight[0]
        else:
            # If nothing in-flight, treat as not found for cancellation semantics
            _log_call("error", key_id, "NOT_FOUND", meta={"job_id": job_id_s})
            return _err("NOT_FOUND", "Job not found (business rule: job must exist, belong to the authenticated key, and be in-flight to cancel)")

    # Enforce lifecycle transitions
    current = job.get("status")
    if current in ("succeeded", "failed", "cancelled"):
        _log_call("error", key_id, "CONFLICT", meta={"job_id": job.get("id"), "status": current})
        return _err("CONFLICT", "Job is already in a terminal state (business rule: cannot cancel succeeded/failed/cancelled jobs)", status=current)

    allowed = {"queued": ("running", "cancelled"), "running": ("succeeded", "failed", "cancelled")}
    if current not in allowed or "cancelled" not in allowed[current]:
        _log_call("error", key_id, "INVALID_TRANSITION", meta={"job_id": job.get("id"), "from": current, "to": "cancelled"})
        return _err("INVALID_TRANSITION", "Cancellation not permitted by lifecycle", from_status=current, to_status="cancelled")

    job["status"] = "cancelled"
    job["finished_at"] = now_iso
    job["updated_at"] = now_iso
    if reason is not None and reason.strip():
        job["error_code"] = "CANCELLED_BY_USER"
        job["error_message"] = reason.strip()
    else:
        job["error_code"] = "CANCELLED_BY_USER"
        job["error_message"] = "Cancelled"

    _save("analysis_jobs.json", analysis_jobs)
    _log_call("ok", key_id, None, meta={"job_id": job.get("id")})
    return {"job": job}

