    usage_row["updated_at"] = now_iso
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("usage_daily.json", usage_daily)
    _save("api_keys.json", api_keys)

    # Resolve job: strict if a real job id; lenient fallback otherwise.
    job = None
    if job_id_s.startswith("serp_job_"):
        for j in analysis_jobs:
            if isinstance(j, dict) and j.get("id") == job_id_s and j.get("api_key_id") == key_id:
                job = j
                break
        if not job:
            _log_call("error", key_id, "NOT_FOUND", meta={"job_id": job_id_s})
            return _err("NOT_FOUND", "Job not found (business rule: job must exist and belong to the authenticated key)")
    else:
        # Lenient: choose most recent analyze_serp job for the key
        candidates = []
        for j in analysis_jobs:
            if isinstance(j, dict) and j.get("api_key_id") == key_id and j.get("tool_name") == "analyze_serp":
                candidates.append(j)
        def _parse_dt(s):
            if not isinstance(s, str) or not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        candidates.sort(key=lambda r: (_parse_dt(r.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
        if candidates:
            job = candidates[0]
        else:
            _log_call("error", key_id, "NOT_FOUND", meta={"job_id": job_id_s})
            return _err("NOT_FOUND", "Job not found (business rule: job must exist and belong to the authenticated key)")

    # Find snapshot linked by analysis_job_id
    snap = None
    for s in serp_snapshots:
        if isinstance(s, dict) and s.get("analysis_job_id") == job.get("id"):
            snap = s
            break
    if not snap:
        _log_call("error", key_id, "NOT_FOUND", meta={"job_id": job.get("id")})
        return _err("NOT_FOUND", "SERP snapshot not found (business rule: analyze_serp success must create exactly one snapshot)")

    # Respect purged retention behavior + include_raw flag
    out = dict(snap)
    if out.get("status") == "purged":
        out["raw_serp"] = None
        out["results"] = []
        # keep serp_features small; if it exists but is large, leave as-is since rule does not require purging it
        if not isinstance(out.get("serp_features"), list):
            out["serp_features"] = []
    else:
        if include_raw is not True:
            out["raw_serp"] = None

    _log_call("ok", key_id, None, meta={"job_id": job.get("id"), "snapshot_id": out.get("id")})
    return {"job": job, "snapshot": out}

