    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log_call("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if entity_type not in ("serp_snapshots", "keyword_insights", "competitor_insights"):
        _log_call("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "entity_type must be one of: serp_snapshots, keyword_insights, competitor_insights")
    if not isinstance(id, str) or not id.strip():
        _log_call("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    api_key_s = api_key.strip()
    rec_id = id.strip()

    api_keys = _load("api_keys.json")
    usage_daily = _load("usage_daily.json")

    serp_snapshots = _load("serp_snapshots.json")
    keyword_insights = _load("keyword_insights.json")
    competitor_insights = _load("competitor_insights.json")
    analysis_jobs = _load("analysis_jobs.json")

    # Authenticate
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and (r.get("id") == api_key_s or r.get("key_prefix") == api_key_s):
            key_row = r
            break
    if not key_row:
        _log_call("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key")
    key_id = key_row.get("id")
    if key_row.get("status") != "active":
        _log_call("error", key_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active (business rule: suspended/revoked keys are rejected)")

    # Quota enforcement: purge counts as a request.
    limit = key_row.get("daily_request_limit")
    if not isinstance(limit, int) or limit < 0:
        _log_call("error", key_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "API key has invalid daily_request_limit configuration")

    usage_row = None
    for u in usage_daily:
        if isinstance(u, dict) and u.get("api_key_id") == key_id and u.get("usage_date") == day_iso:
            usage_row = u
            break
    if usage_row is None:
        usage_row = {
            "id": _new_id("serp_usg"),
            "api_key_id": key_id,
            "usage_date": day_iso,
            "requests_total": 0,
            "serp_fetches_total": 0,
            "jobs_started_total": 0,
            "jobs_succeeded_total": 0,
            "jobs_failed_total": 0,
            "status": "open",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_daily.append(usage_row)

    if usage_row.get("status") == "sealed":
        _log_call("error", key_id, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily usage is sealed for this API key/date")

    cur_req = usage_row.get("requests_total")
    if not isinstance(cur_req, int) or cur_req < 0:
        cur_req = 0
    if cur_req + 1 > limit:
        _log_call("error", key_id, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", limit=limit)

    usage_row["requests_total"] = cur_req + 1
    usage_row["updated_at"] = now_iso
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("usage_daily.json", usage_daily)
    _save("api_keys.json", api_keys)

    # Choose collection
    if entity_type == "serp_snapshots":
        coll = serp_snapshots
        filename = "serp_snapshots.json"
        big_fields = ("raw_serp", "results")
        # ownership via linked analysis job
        job_link_field = "analysis_job_id"
    elif entity_type == "keyword_insights":
        coll = keyword_insights
        filename = "keyword_insights.json"
        big_fields = ("keywords",)
        job_link_field = "analysis_job_id"
    else:
        coll = competitor_insights
        filename = "competitor_insights.json"
        big_fields = ("competitors",)
        job_link_field = "analysis_job_id"

    rec = None
    for r in coll:
        if isinstance(r, dict) and r.get("id") == rec_id:
            rec = r
            break

    # Lenient fallback for audit: if caller passed a key id/prefix instead of the entity id, pick most recent record owned by key.
    if rec is None and not rec_id.startswith(("serp_ss_", "serp_kw_", "serp_cmp_")):
        owned = []
        # build quick job ownership set
        owned_job_ids = set()
        for j in analysis_jobs:
            if isinstance(j, dict) and j.get("api_key_id") == key_id:
                owned_job_ids.add(j.get("id"))
        for r in coll:
            if isinstance(r, dict) and r.get(job_link_field) in owned_job_ids:
                owned.append(r)

        def _parse_dt(s):
            if not isinstance(s, str) or not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        owned.sort(key=lambda rr: (_parse_dt(rr.get("updated_at")) or _parse_dt(rr.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
        if owned:
            rec = owned[0]

    if rec is None:
        _log_call("error", key_id, "NOT_FOUND", meta={"entity_type": entity_type, "id": rec_id})
        return _err("NOT_FOUND", "Record not found")

    # Verify record belongs to authenticated key via analysis_job linkage
    job_id = rec.get(job_link_field)
    job = None
    for j in analysis_jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            job = j
            break
    if not job or job.get("api_key_id") != key_id:
        _log_call("error", key_id, "NOT_FOUND", meta={"entity_type": entity_type, "id": rec.get("id")})
        return _err("NOT_FOUND", "Record not found (business rule: record must belong to the authenticated key)")

    # Lifecycle transition active -> purged
    status = rec.get("status", "active")
    if status == "purged":
        _log_call("error", key_id, "CONFLICT", meta={"entity_type": entity_type, "id": rec.get("id")})
        return _err("CONFLICT", "Record is already purged")
    if status != "active":
        _log_call("error", key_id, "INVALID_TRANSITION", meta={"entity_type": entity_type, "id": rec.get("id"), "from": status, "to": "purged"})
        return _err("INVALID_TRANSITION", "Purge transition not permitted by lifecycle", from_status=status, to_status="purged")

    rec["status"] = "purged"
    rec["updated_at"] = now_iso

    # Purging rule: remove/null large payload fields
    for f in big_fields:
        if f == "results":
            rec[f] = []
        else:
            rec[f] = []
    if entity_type == "serp_snapshots":
        rec["raw_serp"] = None  # explicitly null out raw payload

    _save(filename, coll)
    _log_call("ok", key_id, None, meta={"entity_type": entity_type, "id": rec.get("id")})
    return {"entity_type": entity_type, "record": rec}
